const UI={lang:'ar',dashboard:null,roles:[],restoreFocus:null};
const $=(s)=>document.querySelector(s);const $$=(s)=>[...document.querySelectorAll(s)];
function tr(key){return COPY[UI.lang][key]??COPY.ar[key]??key}
function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function loadData(){const [health,registry,tasks]=await Promise.all([fetch('http://127.0.0.1:8766/api/health').then(r=>{if(!r.ok)throw Error('local API unavailable');return r.json()}),fetch('http://127.0.0.1:8766/api/roles').then(r=>{if(!r.ok)throw Error('role registry unavailable');return r.json()}),fetch('http://127.0.0.1:8766/api/tasks').then(r=>{if(!r.ok)throw Error('task store unavailable');return r.json()})]);UI.health=health;UI.roles=registry.roles;UI.dashboard={data_as_of:new Date().toISOString(),tasks:tasks.tasks.map(t=>{const role=registry.roles.find(r=>r.role_id===t.role_id);const elapsed=t.completed_at?Math.max(0,new Date(t.completed_at)-new Date(t.created_at)):null;return {...t,name_ar:role?.name_ar||t.role_id,name_en:role?.name_en||t.role_id,runtime_display:elapsed===null?'—':`${(elapsed/1000).toFixed(1)} s`,result:t.result||{output:t.error||''}}})};document.querySelector('#task-count').textContent=UI.dashboard.tasks.length;render();populateTaskRoles();$('#refresh-data').dataset.updated='true';announce(`${tr('liveLocal')}: ${UI.dashboard.tasks.length}`)}
function announce(message){let el=$('#announcer');if(!el){el=document.createElement('div');el.id='announcer';el.className='sr-only';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.append(el)}el.textContent=message}
function setLanguage(lang){UI.lang=lang;document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;el.textContent=tr(key)});$$('[data-placeholder-ar]').forEach(el=>el.placeholder=el.dataset[`placeholder${lang==='ar'?'Ar':'En'}`]);$$('[data-i18n-title-ar]').forEach(el=>el.title=el.dataset[`i18nTitle${lang==='ar'?'Ar':'En'}`]);$('#lang-toggle').textContent=lang==='ar'?'English':'العربية';$('#lang-toggle').setAttribute('aria-label',lang==='ar'?'Switch to English':'التبديل إلى العربية');if(UI.dashboard)render();}
function statusPill(status){let cls=status==='completed'?'success':status==='waiting'?'warning':'neutral';return `<span class="pill ${cls}">${escapeHTML(COPY[UI.lang].stateNames[status]||status)}</span>`}
function renderTasks(){const query=$('#task-search').value.trim().toLocaleLowerCase();const filter=$('#status-filter').value;const tasks=(UI.dashboard?.tasks||[]).filter(t=>(filter==='all'||t.status===filter)&&(!query||[t.task_id,t.trace_id,t.name_ar,t.name_en,t.role_id].join(' ').toLocaleLowerCase().includes(query)));$('#operations-body').innerHTML=tasks.map((t,i)=>{const r=UI.roles.find(x=>x.role_id===t.role_id);return `<tr><td><span class="task-name">${escapeHTML(t.input.slice(0,90))}</span><small class="task-meta">${escapeHTML(t.task_id)}</small></td><td>${escapeHTML(r?UI.lang==='ar'?r.name_ar:r.name_en:t.role_id)}</td><td>${statusPill(t.status)}</td><td class="duration">${escapeHTML(t.runtime_display)}</td><td><button class="trace-link" data-task-index="${i}" type="button" aria-label="${UI.lang==='ar'?'تفاصيل التتبع':'Open trace details'} ${escapeHTML(t.trace_id)}">${escapeHTML(t.trace_id)}</button></td></tr>`}).join('');$('#empty-state').hidden=tasks.length>0;$('#empty-state').textContent=tasks.length?tr('noResults'):tr('noTasksYet');$$('[data-task-index]').forEach(btn=>btn.addEventListener('click',()=>openTask(tasks[Number(btn.dataset.taskIndex)],btn)));$('#metric-total').textContent=UI.dashboard?.tasks.length||0;$('#metric-completed').textContent=UI.dashboard?.tasks.filter(t=>t.status==='completed').length||0;$('#metric-failed').textContent=UI.dashboard?.tasks.filter(t=>t.status==='failed').length||0;}
function populateTaskRoles(){const select=$('#new-task-role');const chosen=select.value||'D-00';select.innerHTML=UI.roles.map(r=>`<option value="${escapeHTML(r.role_id)}">${escapeHTML(r.role_id)} · ${escapeHTML(UI.lang==='ar'?r.name_ar:r.name_en)}</option>`).join('');if(UI.roles.some(r=>r.role_id===chosen))select.value=chosen;}
function teamKey(role){return role.team_id==='D'?'D':role.team_id}
function renderRoles(){const teamSelect=$('#team-filter');const current=teamSelect.value;const groups=[...new Map(UI.roles.map(r=>[teamKey(r),r.team_name])).entries()].sort((a,b)=>a[0].localeCompare(b[0]));teamSelect.innerHTML=`<option value="all">${tr('allTeams')}</option>`+groups.map(([id])=>`<option value="${escapeHTML(id)}">${escapeHTML(COPY[UI.lang].teamNames[id]||id)}</option>`).join('');if([...teamSelect.options].some(o=>o.value===current))teamSelect.value=current;const q=$('#role-search').value.toLocaleLowerCase();const team=teamSelect.value;const state=$('#role-status-filter').value;const roles=UI.roles.filter(r=>(team==='all'||teamKey(r)===team)&&(state==='all'||(state==='mock'?r.activation_state==='MOCK_TESTED':r.activation_state==='SPECIFIED'))&&(!q||`${r.name_ar} ${r.name_en} ${r.role_id} ${r.team_name}`.toLocaleLowerCase().includes(q)));$('#role-list').innerHTML=roles.map(r=>`<article class="role-card"><strong lang="ar" dir="rtl" title="${escapeHTML(r.name_ar)}">${escapeHTML(r.name_ar)}</strong><small class="role-en" lang="en" dir="ltr">${escapeHTML(r.name_en)}</small><small>${escapeHTML(COPY[UI.lang].teamNames[teamKey(r)]||r.team_name)} · ${escapeHTML(r.role_id)}</small><span class="role-badge ${r.activation_state==='MOCK_TESTED'?'mock':''}">${r.activation_state==='MOCK_TESTED'?tr('roleState.mock'):tr('roleState.specified')}</span></article>`).join('');$('#role-empty').hidden=roles.length>0;}
function render(){renderTasks();renderRoles();populateTaskRoles();if(UI.health){$('.status-panel .panel-heading .pill').textContent=UI.lang==='ar'?'محلي متصل':'Local online';$('.status-panel .panel-heading .pill').className='pill success';const rows=$$('.status-panel .health-row');if(rows[0]){rows[0].querySelector('strong').textContent='n8n local';rows[0].querySelector('small').textContent='n8n 2.43.7 · 127.0.0.1';rows[0].querySelector('.health-state').textContent=UI.lang==='ar'?'متصل':'Online';}if(rows[1]){rows[1].querySelector('strong').textContent='Ollama · qwen3:8b';rows[1].querySelector('small').textContent=UI.lang==='ar'?'استدلال محلي حقيقي':'Real local inference';rows[1].querySelector('.health-state').textContent=UI.lang==='ar'?'محلي':'Local';}if(rows[2]){rows[2].querySelector('small').textContent=UI.lang==='ar'?'مهام دائمة في SQLite':'Persisted tasks in SQLite';rows[2].querySelector('.health-state').textContent=UI.lang==='ar'?'محلي':'Local';}}$('.data-stamp span:last-child').textContent=tr('liveLocal');}
async function openTask(task,button){UI.restoreFocus=button;try{const response=await fetch(`http://127.0.0.1:8766/api/tasks/${encodeURIComponent(task.task_id)}`);if(response.ok)task=await response.json()}catch{}const role=UI.roles.find(r=>r.role_id===task.role_id);const values=[[tr('taskName'),task.input],[tr('role'),role?(UI.lang==='ar'?role.name_ar:role.name_en):task.role_id],[UI.lang==='ar'?'معرّف المهمة':'Task ID',task.task_id],[UI.lang==='ar'?'معرّف التتبع':'Trace ID',task.trace_id],[tr('status'),COPY[UI.lang].stateNames[task.status]||task.status],[tr('runtime'),task.runtime_display],[UI.lang==='ar'?'النموذج':'Model',task.result?.model||'—'],[UI.lang==='ar'?'النتيجة':'Result',task.result?.output||task.result?.error||'']];const rows=(task.steps||[]).map((step,i)=>[`${UI.lang==='ar'?'المرحلة':'Step'} ${i+1} · ${step.role_id} (${step.step_type})`,`${step.status}${step.n8n_execution_id?` · n8n #${step.n8n_execution_id}`:''}\n${step.output||step.error||''}`]);if(task.collaboration)rows.push([UI.lang==='ar'?'نتيجة المراجع':'Reviewer verdict',task.collaboration.review_output]);rows.push([UI.lang==='ar'?'عناصر الذاكرة المشتركة':'Shared memory entries',String((task.memory||[]).length)]);$('#dialog-content').innerHTML=`<dl class="detail-list">${[...values,...rows].map(([k,v],i)=>`<dt>${escapeHTML(k)}</dt><dd ${i===2||i===3?'dir="ltr"':''}>${escapeHTML(v)}</dd>`).join('')}</dl><p class="detail-notice">${escapeHTML(UI.lang==='ar'?'استدلال محلي عبر Ollama؛ زمن الاستجابة المقاس يشمل التنسيق وn8n. لا توجد صلاحيات أدوات أو تكلفة مزوّد API.':'Local Ollama inference; measured time includes orchestration and n8n. No tool permissions or API provider cost.')}</p>`;const dlg=$('#task-dialog');dlg.showModal();$('#dialog-title').focus();}
function closeDialog(){const d=$('#task-dialog');if(d.open)d.close();UI.restoreFocus?.focus();}
function exportSummary(){const d=UI.dashboard;const redacted={schema_version:'local-task-export.v1',data_as_of:d.data_as_of,provider:'ollama-local',tasks:d.tasks.map(({task_id,trace_id,role_id,status,runtime_display,result})=>({task_id,trace_id,role_id,status,runtime_display,model:result?.model||null,n8n_execution_id:result?.n8n_execution_id||null}))};const blob=new Blob([JSON.stringify(redacted,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='wejdan-local-task-summary.json';a.click();URL.revokeObjectURL(url);announce(UI.lang==='ar'?'تم تصدير ملخص المهام المحلي.':'Local task summary exported.')}
async function submitTask(event){event.preventDefault();const input=$('#new-task-input').value.trim();const role_id=$('#new-task-role').value;if(!input)return;const button=$('#submit-task'),status=$('#task-submit-status');button.disabled=true;status.classList.remove('sr-only');status.textContent=tr('taskRunning');try{const response=await fetch('http://127.0.0.1:8766/api/tasks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({input,role_id,collaborate:$('#task-collaborate').checked,reviewer_role_id:'QA-01'})});const result=await response.json();if(!response.ok)throw Error(result.detail||result.error||'Task failed');$('#new-task-input').value='';await loadData();status.textContent=`${tr('taskCompleted')} ${result.task_id} · ${result.trace_id}${result.collaboration?' · QA‑01 reviewed':''}`;announce(status.textContent)}catch(error){status.textContent=`${tr('taskFailed')}: ${error.message}`;announce(status.textContent)}finally{button.disabled=false}}
document.addEventListener('DOMContentLoaded',()=>{loadData().catch(err=>{console.error(err);announce(UI.lang==='ar'?'تعذر الاتصال بالخدمات المحلية. شغّلي n8n وAPI المحلي.':'Could not reach local services. Start n8n and the local API.')});$('#task-form').addEventListener('submit',submitTask);$('#lang-toggle').addEventListener('click',()=>setLanguage(UI.lang==='ar'?'en':'ar'));$('#task-search').addEventListener('input',renderTasks);$('#status-filter').addEventListener('change',renderTasks);$('#role-search').addEventListener('input',renderRoles);$('#team-filter').addEventListener('change',renderRoles);$('#role-status-filter').addEventListener('change',renderRoles);$('#refresh-data').addEventListener('click',()=>loadData().catch(()=>announce(tr('apiUnavailable'))));$('#export-report').addEventListener('click',exportSummary);$('#dialog-close').addEventListener('click',closeDialog);$('#task-dialog').addEventListener('click',e=>{if(e.target===$('#task-dialog'))closeDialog()});$('#task-dialog').addEventListener('cancel',()=>{UI.restoreFocus?.focus()});setLanguage('ar')});
